python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import subprocess, tempfile

html = Path('earth.html').read_text(encoding='utf-8')

class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void:
            return
        if not self.stack:
            self.errors.append(f'unexpected </{tag}>')
            return
        if self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            self.errors.append(f'mismatched </{tag}> while <{self.stack[-1]}> is open')
            while self.stack and self.stack[-1] != tag:
                self.stack.pop()
            if self.stack:
                self.stack.pop()
        else:
            self.errors.append(f'unmatched </{tag}>')

parser = Checker()
parser.feed(html)
if parser.stack:
    parser.errors.append('unclosed: ' + ', '.join(parser.stack))
if parser.errors:
    print('HTML structure issues:')
    print('\n'.join(parser.errors))
else:
    print('HTML structure check: OK')

start = html.index('<script>') + len('<script>')
end = html.index('</script>', start)
with tempfile.NamedTemporaryFile('w', suffix='.js', delete=False) as f:
    f.write(html[start:end])
    path = f.name
result = subprocess.run(['node', '--check', path], capture_output=True, text=True)
print('JS syntax check:', 'OK' if result.returncode == 0 else result.stderr.strip())
PY

