from pathlib import Path
s=Path('source.kt').read_text()
stack=[]
i=0
line=1
pairs={')':'(',']':'[','}':'{'}
while i < len(s):
    c=s[i]
    if c=='\n':
        line+=1; i+=1; continue
    if c=='/' and i+1<len(s) and s[i+1]=='/':
        while i<len(s) and s[i]!='\n': i+=1
        continue
    if c=='/' and i+1<len(s) and s[i+1]=='*':
        i+=2
        while i+1<len(s) and not (s[i]=='*' and s[i+1]=='/'):
            if s[i]=='\n': line+=1
            i+=1
        i+=2; continue
    if c=='"':
        i+=1
        while i<len(s):
            if s[i]=='\\': i+=2; continue
            if s[i]=='"': i+=1; break
            if s[i]=='\n': line+=1
            i+=1
        continue
    if c=="'":
        i+=1
        while i<len(s):
            if s[i]=='\\': i+=2; continue
            if s[i]=="'": i+=1; break
            i+=1
        continue
    if c in '([{': stack.append((c,line))
    elif c in ')]}':
        if not stack or stack[-1][0]!=pairs[c]:
            print('MISMATCH', c, 'line', line, 'top', stack[-1] if stack else None); break
        stack.pop()
    i+=1
else:
    print('balanced' if not stack else f'unclosed {stack[-5:]}')
