def _update_castling_rights(
    castling: Set[str],
    move: Move,
    piece: str,
    captured: str,
) -> Set[str]:
    if not castling:
        return castling

    rights = set(castling)
    from_row, from_col, to_row, to_col = move

    if piece == "K":
        rights.discard("K")
        rights.discard("Q")
    elif piece == "k":
        rights.discard("k")
        rights.discard("q")
    elif piece == "R":
        if (from_row, from_col) == (7, 0):
            rights.discard("Q")
        elif (from_row, from_col) == (7, 7):
            rights.discard("K")
    elif piece == "r":
        if (from_row, from_col) == (0, 0):
            rights.discard("q")
        elif (from_row, from_col) == (0, 7):
            rights.discard("k")

    if captured == "R":
        if (to_row, to_col) == (7, 0):
            rights.discard("Q")
        elif (to_row, to_col) == (7, 7):
            rights.discard("K")
    elif captured == "r":
        if (to_row, to_col) == (0, 0):
            rights.discard("q")
        elif (to_row, to_col) == (0, 7):
            rights.discard("k")

    return rights


